const UserNameAvailableResponseSchema = z
  .object({
    error: ErrorResponseSchema.exactOptional(),
    hasError: z.boolean().exactOptional(),
    errorDescription: z.string().exactOptional(),
    isValid: z.boolean().exactOptional(),
    isAvailable: z.boolean().exactOptional(),
    suggestedUserName: z
      .array(z.string())
      .superRefine((items, ctx) => {
        const seen = new Map()
        for (const [i, val] of items.entries()) {
          const key = JSON.stringify(val)
          if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
          else seen.set(key, i)
        }
      })
      .exactOptional(),
  })
  .openapi({ required: [] })
  .openapi('UserNameAvailableResponse')

