const TypecodesSchema = z
  .enum([
    'BA',
    'CA',
    'DA',
    'EA',
    'MF',
    'OE',
    'PR',
    'SE',
    'SG',
    'SM',
    'T2',
    'TO',
    'UA',
    'M8',
    'PS',
    'DL',
    'PT',
    'CB',
    'MS',
    'TD',
    'ST',
    'TI',
    'CT',
  ])
  .openapi({
    description:
      'Many FYI endpoints reference a "typecode" value. The table below lists the available codes and what they correspond to.\n  * `BA` - Borrow Availability\n  * `CA` - Comparable Algo\n  * `DA` - Dividends Advisory\n  * `EA` - Upcoming Earnings\n  * `MF` - Mutual Fund Advisory\n  * `OE` - Option Expiration\n  * `PR` - Portfolio Builder Rebalance\n  * `SE` - Suspend Order on Economic Event\n  * `SG` - Short Term Gain turning Long Term\n  * `SM` - System Messages\n  * `T2` - Assignment Realizing Long-Term Gains\n  * `TO` - Takeover\n  * `UA` - User Alert\n  * `M8` - M871 Trades\n  * `PS` - Platform Use Suggestions\n  * `DL` - Unexercised Option Loss Prevention Reminder\n  * `PT` - Position Transfer\n  * `CB` - Missing Cost Basis\n  * `MS` - Milestones\n  * `TD` - MiFID || 10% Deprecation Notice\n  * `ST` - Save Taxes\n  * `TI` - Trade Idea\n  * `CT` - Cash Transfer\n',
  })
  .openapi('Typecodes')

