export const postGwApiV1EchoSignedJwtRoute = createRoute({
  method: 'post',
  path: '/gw/api/v1/echo/signed-jwt',
  tags: ['Utilities Echo'],
  summary: 'Echo A Request With Signed JWT Security Policy Back After Validation.',
  description: '<br>**Scope**: `echo.write`<br>**Security Policy**: `Signed JWT`',
  operationId: 'createEchoSignedJwt',
  request: { body: SignedJwtEchoRequestBodyRequestBody },
  responses: {
    200: {
      description: 'Returns a JSON object containing the request parameters.',
      content: { 'application/json': { schema: EchoResponseSchema } },
    },
    401: {
      description: 'Returns a Problem detail instance representing an unauthorized request.',
      content: { 'application/problem+json': { schema: InvalidAccessTokenResponseSchema } },
    },
    403: {
      description: 'Returns a Problem detail instance representing a forbidden request.',
      content: { 'application/problem+json': { schema: InsufficientScopeResponseSchema } },
    },
    500: {
      description: 'Returns a Problem detail instance representing an internal server error.',
      content: { 'application/problem+json': { schema: InternalServerErrorResponseSchema } },
    },
  },
  security: [{ oauth2Bearer: [] }],
})

