export const postV1ApiFaModelInvestDivestRoute = createRoute({
  method: 'post',
  path: '/v1/api/fa/model/invest-divest',
  tags: ['Trading FA Model Portfolios'],
  summary: 'Invest Account Into Model',
  description:
    'Submit invest or divest instructions for one or more accounts into a **single** destination model, with a **per-account** cash amount. Each entry in `accountList` pairs an account identifier with the individual `amtToInvest` value applied to that account (positive to invest, negative to divest).\n\nConstraints and comparison to `/fa/model/tws-invest-divest`:\n * Only a **single model** may be targeted per request (the top-level `model`\n   field). To invest into multiple models in one call, use\n   `/fa/model/tws-invest-divest` and its `modelList`.\n * The model must be denominated in a **single currency**; multi-currency\n   models are not supported by this endpoint. Use `/fa/model/tws-invest-divest`\n   for models holding instruments across multiple currencies.\n * FA pre-trade allocation **groups are not supported** here â€” each account\n   and its individual investment amount must be listed explicitly in\n   `accountList`.\n * Because each account is listed individually, this endpoint allows a\n   **different investment amount per account**. `/fa/model/tws-invest-divest`,\n   by contrast, splits a single `amtToInvest` equally across accounts when a\n   `group` or `accountList` is used.\n',
  operationId: 'setAccountinvestmentInModel',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              reqID: z
                .preprocess(
                  (val) =>
                    typeof val === 'number' && Number.isSafeInteger(val)
                      ? BigInt(val)
                      : typeof val === 'string' && /^-?\d+$/.test(val)
                        ? BigInt(val)
                        : val,
                  z.int64(),
                )
                .exactOptional()
                .openapi({
                  type: 'integer',
                  format: 'int64',
                  description: 'Request identifier to uniquely track a request.',
                }),
              model: z
                .string()
                .exactOptional()
                .openapi({ description: 'Define the model to invest accounts into.' }),
              accountList: z
                .array(
                  z
                    .object({
                      account: z
                        .string()
                        .exactOptional()
                        .openapi({ description: 'Account identifier to invest.' }),
                      amtToInvest: z
                        .number()
                        .exactOptional()
                        .openapi({
                          description: 'Amount of cash to invest in the model from the account.',
                        }),
                    })
                    .openapi({ required: [] }),
                )
                .exactOptional()
                .openapi({ description: 'Collection of accounts to invest in a model.' }),
            })
            .openapi({ required: [] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Successfully submitted model investment.',
      content: {
        'application/json': {
          schema: z
            .object({
              reqID: z
                .string()
                .exactOptional()
                .openapi({
                  description: 'Request identifier to uniquely track a request.',
                  example: '540607',
                }),
              subscriptionStatus: z
                .preprocess(
                  (val) =>
                    typeof val === 'number' && Number.isSafeInteger(val)
                      ? BigInt(val)
                      : typeof val === 'string' && /^-?\d+$/.test(val)
                        ? BigInt(val)
                        : val,
                  z.int64(),
                )
                .exactOptional()
                .openapi({
                  type: 'integer',
                  format: 'int64',
                  description: 'Describes if the model is in polling mode.',
                }),
            })
            .openapi({ required: [] }),
          examples: {
            success: { value: { reqID: '130', subscriptionKey: '2', subscriptionStatus: 0 } },
          },
        },
      },
    },
    401: UnauthorizedResponse,
    500: InternalServerErrorResponse,
    503: ServiceUnavailableResponse,
  },
  security: [{ ssoBearer: [] }],
})

