export const postV1ApiFaModelTwsInvestDivestRoute = createRoute({
  method: 'post',
  path: '/v1/api/fa/model/tws-invest-divest',
  tags: ['Trading FA Model Portfolios'],
  summary: 'TWS Invest / Divest',
  description:
    'Submit TWS-style invest or divest instructions across **one or more destination models** for a set of accounts. Positive `amtToInvest` values invest cash into the target model; negative values divest. The response returns the resulting allocation plan and cash transfers between the source cash pool and each destination model.\n\nThe set of accounts to invest can be specified in one of three **mutually exclusive** ways:\n * `account` - a single U-account identifier\n   (e.g. `"account": "DU12349"`).\n * `accountList` - an explicit list of U-account identifiers\n   (e.g. `"accountList": ["DU12349", "DU12350", "DU12351"]`).\n * `group` - the name of an FA pre-trade allocation group\n   (e.g. `"group": "Group1"`), or `"All"` to include every account under the\n   advisor. When `accountList` or `group` is used, each `amtToInvest` value is\n   **divided equally** across the resolved accounts.\n\n\nFeature comparison vs. `/fa/model/invest-divest`:\n * `tws-invest-divest` supports models denominated in **multiple currencies**;\n   `invest-divest` supports only single-currency models.\n * `tws-invest-divest` accepts **multiple destination models** per request\n   (via `modelList`); `invest-divest` targets a single model per request.\n * `invest-divest` allows a **different investment amount per account**\n   because each account is listed individually with its own `amtToInvest`.\n   FA pre-trade allocation groups are not supported by `invest-divest`.\n * When `tws-invest-divest` uses `group` or `accountList`, the single\n   `amtToInvest` is split **equally** across all resolved accounts.\n',
  operationId: 'twsInvestDivest',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              reqID: z
                .preprocess(
                  (val) =>
                    typeof val === 'number' && Number.isSafeInteger(val)
                      ? BigInt(val)
                      : typeof val === 'string' && /^-?\d+$/.test(val)
                        ? BigInt(val)
                        : val,
                  z.int64(),
                )
                .openapi({
                  type: 'integer',
                  format: 'int64',
                  description: 'Request identifier to uniquely track a request.',
                  example: 398889,
                }),
              account: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Single U-account identifier submitting the invest/divest instructions. Mutually exclusive with `accountList` and `group`.\n',
                  example: 'DU12349',
                }),
              accountList: z
                .array(z.string())
                .exactOptional()
                .openapi({
                  description:
                    'Explicit list of U-account identifiers to invest/divest. Each `amtToInvest` value in `modelList` is divided equally across the listed accounts. Mutually exclusive with `account` and `group`.\n',
                  example: ['DU12349', 'DU12350', 'DU12351'],
                }),
              group: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Name of an FA pre-trade allocation group whose member accounts should receive the invest/divest instructions. Use `"All"` to target every account under the advisor. When supplied, each `amtToInvest` value in `modelList` is divided equally across the resolved group members. Mutually exclusive with `account` and `accountList`.\n',
                  example: 'Group1',
                }),
              modelList: z
                .array(
                  z
                    .object({
                      investCurrency: z
                        .string()
                        .exactOptional()
                        .openapi({
                          description: 'Currency (ISO 4217) of the invest/divest amount.',
                          example: 'USD',
                        }),
                      amtToInvest: z
                        .number()
                        .exactOptional()
                        .openapi({
                          description:
                            'Amount of cash to invest into the model. Use a negative value to divest.',
                          example: 1000,
                        }),
                      model: z
                        .string()
                        .exactOptional()
                        .openapi({
                          description: 'Destination model for the invest/divest instruction.',
                          example: 'MODEL-API-DEMO',
                        }),
                    })
                    .openapi({ required: [] }),
                )
                .openapi({
                  description: 'List of invest/divest instructions, one per model destination.',
                }),
              subscriptionKey: z
                .string()
                .exactOptional()
                .openapi({
                  description: 'Subscription key. Send an empty string on the initial request.',
                }),
            })
            .openapi({ required: ['modelList', 'reqID'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Successfully computed the invest/divest allocation plan.',
      content: {
        'application/json': {
          schema: TwsInvestDivestResponseSchema,
          examples: {
            success: {
              value: {
                allocations: [
                  {
                    account: 'DU12345',
                    batchNumber: 4,
                    cashQty: '15.73',
                    closePosition: false,
                    conid: 270639,
                    isCashQty: false,
                    model: 'MODEL-API-DEMO',
                    price: '103.256',
                    quantity: '0.1523',
                    relatedRequestAccount: 'DU12345',
                    relatedRequestID: '21449',
                    secType: 'STK',
                  },
                  {
                    account: 'DU12345',
                    batchNumber: 4,
                    cashQty: '206.92',
                    closePosition: false,
                    conid: 76792991,
                    isCashQty: false,
                    model: 'MODEL-API-DEMO',
                    price: '339.489',
                    quantity: '0.6095',
                    relatedRequestAccount: 'DU12345',
                    relatedRequestID: '21449',
                    secType: 'STK',
                  },
                ],
                cashTransfers: [
                  {
                    account: 'DU12345',
                    amt: '3000',
                    batchNumber: 1,
                    ccy: 'USD',
                    destinationModel: 'MODEL-API-DEMO',
                    sourceModel: 'Core',
                  },
                ],
                errors: 'None',
                positionTransfers: [],
                reqID: 398889,
                subscriptionStatus: 1,
                transfersInstructionId: 2,
              },
            },
          },
        },
      },
    },
    401: UnauthorizedResponse,
    500: InternalServerErrorResponse,
    503: ServiceUnavailableResponse,
  },
  security: [{ ssoBearer: [] }],
})

