export const putV1ApiIserverAccountAllocationGroupRoute = createRoute({
  method: 'put',
  path: '/v1/api/iserver/account/allocation/group',
  tags: ['Trading FA Allocation Management'],
  summary: 'Modify Allocation Group',
  description: 'Modify an existing allocation group.',
  operationId: 'modifyAllocationGroup',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              name: z
                .string()
                .openapi({
                  description:
                    'Name used to refer to your allocation group. If prev_name is specified, this will become the new name of the group.',
                  example: 'Group_1_NetLiq',
                }),
              prev_name: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Can be used to rename a group. Using this field will recognize the previous name, while the "name" filed will mark the updated name.',
                  example: 'Group_0_NetLiq',
                }),
              accounts: z
                .array(
                  z
                    .object({
                      name: z
                        .string()
                        .openapi({
                          description: 'The accountId of a given sub-account.',
                          example: 'U1234567',
                        }),
                      amount: z
                        .preprocess(
                          (val) =>
                            typeof val === 'number' && Number.isSafeInteger(val)
                              ? BigInt(val)
                              : typeof val === 'string' && /^-?\d+$/.test(val)
                                ? BigInt(val)
                                : val,
                          z.int64(),
                        )
                        .exactOptional()
                        .openapi({
                          type: 'integer',
                          format: 'int64',
                          description:
                            'The total distribution value for each sub-account for user-defined allocation methods.',
                          example: 10,
                        }),
                    })
                    .openapi({ required: ['name'] }),
                )
                .openapi({
                  description:
                    'An array of accounts that should be held in the allocation group and, if using a User-specified allocaiton method, the value correlated to the allocation.',
                }),
              default_method: AllocationMethodSchema,
            })
            .openapi({ required: ['accounts', 'default_method', 'name'] }),
          examples: {
            Shares: {
              value: {
                name: 'Group_1_Shares',
                prev_name: 'Group_0_Shares',
                default_method: 'S',
                accounts: [
                  { name: 'U456789', amount: 4 },
                  { name: 'U123456', amount: 1 },
                ],
              },
            },
            NetLiq: {
              value: {
                name: 'Group_1_NetLiq',
                prev_name: 'Group_0_NetLiq',
                default_method: 'N',
                accounts: [{ name: 'U456789' }, { name: 'U123456' }],
              },
            },
            EqualQty: {
              value: {
                name: 'Group_1_Equal',
                prev_name: 'Group_0_Equal',
                default_method: 'E',
                accounts: [{ name: 'U456789' }, { name: 'U123456' }],
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Returns a confirmation that the modification was successful.',
      content: {
        'application/json': {
          schema: z.object({ success: z.boolean().exactOptional() }).openapi({ required: [] }),
        },
      },
    },
    401: UnauthorizedResponse,
    500: InternalServerErrorResponse,
    503: ServiceUnavailableResponse,
  },
  security: [{ ssoBearer: [] }],
})

