export const postV1ApiIserverAccountModelCodeOrdersRoute = createRoute({
  method: 'post',
  path: '/v1/api/iserver/account/{modelCode}/orders',
  tags: ['Trading FA Model Portfolios'],
  summary: 'Submit New Model Portfolio Order',
  description:
    'Create Model Portfolio invest or rebalancing order. Submits one or more order instructions against the Model Portfolio identified by `modelCode` in the URL path. Each order entry follows the standard IBKR order submission contract used by `/iserver/account/{accountId}/orders`, with `acctId` set to the target sub-account and orders routed under the model.\n\nThis endpoint returns either a list of successfully submitted order confirmations or a list of reply objects that require follow-up confirmation via `/iserver/reply/{replyId}` before the orders are transmitted.\n',
  operationId: 'submitModelPortfolioOrder',
  request: {
    params: z.object({
      modelCode: z
        .string()
        .openapi({
          param: {
            name: 'modelCode',
            in: 'path',
            description:
              'Name of the target Model Portfolio to receive the invest or rebalancing order.',
            required: true,
            style: 'simple',
            explode: false,
            schema: { type: 'string', example: 'Sample-Model' },
          },
          example: 'Sample-Model',
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              orders: z
                .array(
                  z
                    .object({
                      acctId: z
                        .string()
                        .exactOptional()
                        .openapi({
                          description:
                            'Sub-account identifier the order applies to under the model.',
                          example: 'DU12345',
                        }),
                      conid: z
                        .preprocess(
                          (val) =>
                            typeof val === 'number' && Number.isSafeInteger(val)
                              ? BigInt(val)
                              : typeof val === 'string' && /^-?\d+$/.test(val)
                                ? BigInt(val)
                                : val,
                          z.int64(),
                        )
                        .exactOptional()
                        .openapi({
                          type: 'integer',
                          format: 'int64',
                          description: 'Contract identifier for the instrument to trade.',
                          example: 265598,
                        }),
                      conidex: z
                        .string()
                        .exactOptional()
                        .openapi({
                          description:
                            'Combined contract identifier and routing destination in the form `<conid>@<exchange>`. Optional; if omitted, IBKR default routing is used.\n',
                          example: '265598@SMART',
                        }),
                      secType: z
                        .string()
                        .exactOptional()
                        .openapi({
                          description: 'Security type (e.g. `STK`, `OPT`, `FUT`, `CASH`).',
                          example: 'STK',
                        }),
                      cOID: z
                        .string()
                        .exactOptional()
                        .openapi({
                          description:
                            'Client order identifier. Must be unique per order and can be used to correlate submissions with downstream events.\n',
                          example: 'my-model-order-001',
                        }),
                      parentId: z
                        .string()
                        .exactOptional()
                        .openapi({
                          description:
                            '`cOID` of the parent order when submitting child orders in a bracket or OCA group.\n',
                        }),
                      orderType: z
                        .enum(['MKT', 'LMT', 'STP', 'STOP_LIMIT', 'MIDPRICE', 'TRAIL', 'TRAILLMT'])
                        .exactOptional()
                        .openapi({ description: 'Order type.', example: 'MKT' }),
                      listingExchange: z
                        .string()
                        .exactOptional()
                        .openapi({
                          description: 'Preferred listing exchange for the instrument.',
                          example: 'SMART',
                        }),
                      isSingleGroup: z
                        .boolean()
                        .exactOptional()
                        .openapi({
                          description: 'True to submit the order set as a single OCA group.',
                        }),
                      outsideRTH: z
                        .boolean()
                        .exactOptional()
                        .openapi({
                          description:
                            'True to allow the order to execute outside regular trading hours.',
                        }),
                      price: z
                        .number()
                        .exactOptional()
                        .openapi({
                          description:
                            'Limit price. Required for `LMT` and `STOP_LIMIT` order types.',
                        }),
                      auxPrice: z
                        .number()
                        .exactOptional()
                        .openapi({
                          description:
                            'Stop or trailing price. Required for `STP`, `STOP_LIMIT`, and trailing order types.',
                        }),
                      side: z
                        .enum(['BUY', 'SELL'])
                        .exactOptional()
                        .openapi({ description: 'Order side.', example: 'BUY' }),
                      ticker: z
                        .string()
                        .exactOptional()
                        .openapi({ description: 'Instrument ticker symbol.', example: 'AAPL' }),
                      tif: z
                        .enum(['DAY', 'GTC', 'OPG', 'IOC'])
                        .exactOptional()
                        .openapi({ description: 'Time in force for the order.', example: 'DAY' }),
                      trailingAmt: z
                        .number()
                        .exactOptional()
                        .openapi({
                          description: 'Trailing amount for `TRAIL` / `TRAILLMT` order types.',
                        }),
                      trailingType: z
                        .enum(['amt', '%'])
                        .exactOptional()
                        .openapi({ description: 'Trailing amount type.' }),
                      referrer: z
                        .string()
                        .exactOptional()
                        .openapi({
                          description: 'Optional referrer identifier used for internal tracking.',
                          example: 'ModelPortfolio',
                        }),
                      quantity: z
                        .number()
                        .exactOptional()
                        .openapi({
                          description:
                            'Share quantity to trade. Mutually exclusive with `cashQty`.',
                          example: 100,
                        }),
                      cashQty: z
                        .number()
                        .exactOptional()
                        .openapi({
                          description:
                            'Cash-denominated quantity to trade. Mutually exclusive with `quantity`.',
                        }),
                      fxQty: z
                        .number()
                        .exactOptional()
                        .openapi({ description: 'FX quantity for currency conversion orders.' }),
                      useAdaptive: z
                        .boolean()
                        .exactOptional()
                        .openapi({
                          description: 'True to route the order using the IB Adaptive algorithm.',
                        }),
                      isCcyConv: z
                        .boolean()
                        .exactOptional()
                        .openapi({
                          description: 'True if the order is a currency conversion order.',
                        }),
                      allocationMethod: z
                        .string()
                        .exactOptional()
                        .openapi({
                          description:
                            "FA allocation method used to distribute the order across the model's sub-accounts (e.g. `AvailableEquity`, `NetLiq`, `EqualQuantity`, `PctChange`).\n",
                          example: 'AvailableEquity',
                        }),
                      strategy: z
                        .string()
                        .exactOptional()
                        .openapi({ description: 'Optional algorithmic execution strategy name.' }),
                      strategyParameters: z
                        .object({})
                        .exactOptional()
                        .openapi({
                          description: 'Parameters passed to the selected algorithmic strategy.',
                        }),
                    })
                    .openapi({ required: [] }),
                )
                .openapi({
                  description:
                    'Collection of order instructions to submit against the model portfolio.',
                }),
            })
            .openapi({ required: ['orders'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description:
        'Successfully submitted the model portfolio order(s). The response is either a list of order confirmations, or a list of reply objects requiring follow-up confirmation via `/iserver/reply/{replyId}`.\n',
      content: {
        'application/json': {
          schema: z.array(
            z
              .object({
                order_id: z
                  .string()
                  .exactOptional()
                  .openapi({ description: 'Identifier of the submitted model portfolio order.' }),
                order_status: z
                  .string()
                  .exactOptional()
                  .openapi({
                    description:
                      'Current status of the submitted order (e.g. `PreSubmitted`, `Submitted`, `Filled`).',
                  }),
                encrypt_message: z
                  .string()
                  .exactOptional()
                  .openapi({
                    description: 'Internal encrypted acknowledgement of the submission.',
                  }),
                id: z
                  .string()
                  .exactOptional()
                  .openapi({
                    description:
                      'Reply identifier returned when the order requires additional confirmation. Supply this value to `/iserver/reply/{replyId}` to continue submission.\n',
                  }),
                message: z
                  .array(z.string())
                  .exactOptional()
                  .openapi({
                    description:
                      'Confirmation prompts that must be acknowledged before the order is transmitted.',
                  }),
                isSuspended: z
                  .boolean()
                  .exactOptional()
                  .openapi({
                    description: 'True if the order is suspended pending reply confirmation.',
                  }),
              })
              .openapi({ required: [] }),
          ),
          examples: {
            success: {
              value: [
                { order_id: '1799115492', order_status: 'PreSubmitted', encrypt_message: '1' },
              ],
            },
            replyRequired: {
              value: [
                {
                  id: 'a1b2c3d4-1234-5678-9abc-def012345678',
                  message: [
                    'The following order size is larger than the average daily trading volume for this instrument. Are you sure you want to submit this order?',
                  ],
                  isSuspended: false,
                },
              ],
            },
          },
        },
      },
    },
    400: BadRequestResponse,
    401: UnauthorizedResponse,
    500: InternalServerErrorResponse,
    503: ServiceUnavailableResponse,
  },
  security: [{ ssoBearer: [] }],
})

