export const postV1ApiOauthAccessTokenRoute = createRoute({
  method: 'post',
  path: '/v1/api/oauth/access_token',
  tags: ['Trading OAuth 1.0a'],
  summary: 'Generate An Access Token',
  description:
    'Request an access token for the IB username that has granted authorization to the consumer.',
  operationId: 'reqAccessToken',
  request: {
    headers: z.object({
      Authorization: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'Authorization',
            in: 'header',
            description:
              'OAuth 1.0a authorization request header for request to /access_token endpoint.',
            required: false,
            style: 'simple',
            explode: false,
            schema: {
              type: 'string',
              example:
                'OAuth oauth_verifier="1e1dc5666e87ca5a18e0",oauth_token="e0d75b4c5c1d2c0f2af7",oauth_consumer_key="TESTCONS",oauth_nonce="v235...456h",oauth_signature="af1%252...0nd2",oauth_signature_method="RSA-SHA256",oauth_timestamp="1714489450",realm="test_realm"',
            },
          },
          example:
            'OAuth oauth_verifier="1e1dc5666e87ca5a18e0",oauth_token="e0d75b4c5c1d2c0f2af7",oauth_consumer_key="TESTCONS",oauth_nonce="v235...456h",oauth_signature="af1%252...0nd2",oauth_signature_method="RSA-SHA256",oauth_timestamp="1714489450",realm="test_realm"',
        }),
    }),
  },
  responses: {
    200: {
      description: 'Success response with permanent OAuth access token',
      content: {
        'application/json': {
          schema: z
            .object({
              is_true: z
                .boolean()
                .exactOptional()
                .openapi({
                  description: 'Indicates whether the authorizing username is paper or not.',
                }),
              oauth_token: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Permanent OAuth access token for the consumer with respect to the authorizing username. 20 character hex value.',
                }),
              oauth_token_secret: z
                .string()
                .exactOptional()
                .openapi({ description: 'OAuth token secret value. Base64-encoded string.' }),
            })
            .openapi({ required: [] }),
          examples: {
            Success: {
              value: {
                is_paper: true,
                oauth_token: 'a1b2c3d4e5f6a7b8c9d0',
                oauth_token_secret:
                  '',
              },
            },
          },
        },
      },
    },
    401: UnauthorizedResponse,
    503: ServiceUnavailableResponse,
  },
  security: [{ ssoBearer: [] }],
})

export const postV1ApiOauthLiveSessionTokenRoute = createRoute({
  method: 'post',
  path: '/v1/api/oauth/live_session_token',
  tags: ['Trading OAuth 1.0a'],
  summary: 'Generate A Live Session Token',
  description: 'Generate a Live Session Token shared secret and gain access to Web API.',
  operationId: 'reqLiveSessionToken',
  request: {
    headers: z.object({
      Authorization: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'Authorization',
            in: 'header',
            description:
              'OAuth 1.0a authorization request header for request to /live_session_token endpoint.',
            required: false,
            style: 'simple',
            explode: false,
            schema: {
              type: 'string',
              example:
                'OAuth diffie_hellman_challenge="b393...g6f3",oauth_token="56786fc07bcbabc4584",oauth_consumer_key="TESTCONS",oauth_nonce="v235...456h",oauth_signature="af1%252...0nd2",oauth_signature_method="RSA-SHA256",oauth_timestamp="1714489460",realm="test_realm"',
            },
          },
          example:
            'OAuth diffie_hellman_challenge="b393...g6f3",oauth_token="56786fc07bcbabc4584",oauth_consumer_key="TESTCONS",oauth_nonce="v235...456h",oauth_signature="af1%252...0nd2",oauth_signature_method="RSA-SHA256",oauth_timestamp="1714489460",realm="test_realm"',
        }),
    }),
  },
  responses: {
    200: {
      description: 'Success response with Diffie-Hellman challenge and Signature value',
      content: {
        'application/json': {
          schema: z
            .object({
              diffie_hellman_challenge: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Diffie-Hellman challenge value used to compute live session token locally by client.',
                }),
              live_session_token_signature: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Signature value used to validate successful client-side computation of live session token.',
                }),
              live_session_token_expiration: z
                .preprocess(
                  (val) =>
                    typeof val === 'number' && Number.isSafeInteger(val)
                      ? BigInt(val)
                      : typeof val === 'string' && /^-?\d+$/.test(val)
                        ? BigInt(val)
                        : val,
                  z.int64(),
                )
                .exactOptional()
                .openapi({
                  type: 'integer',
                  format: 'int64',
                  description:
                    'Unix timestamp in milliseconds of time of live session token computation by IB. Live session tokens are valid for 24 hours from this time.',
                }),
            })
            .openapi({ required: [] }),
          examples: {
            Success: {
              value: {
                diffie_hellman_response:
                  '',
                live_session_token_signature: '712549e22ba937ab10bc8d571bd3a9c20c43d7cb',
                live_session_token_expiration: 1714669716258,
              },
            },
          },
        },
      },
    },
    401: UnauthorizedResponse,
    503: ServiceUnavailableResponse,
  },
  security: [{ ssoBearer: [] }],
})

