export const getGwApiV1RequestsRequestIdStatusRoute = createRoute({
  method: 'get',
  path: '/gw/api/v1/requests/{requestId}/status',
  tags: ['Account Management Utilities'],
  summary: 'Get Status Of A Request',
  description:
    'Returns status for account management request<br><br>**Scope**: `accounts.read`<br>**Security Policy**: `HTTPS`',
  operationId: 'getRequestsStatus',
  request: {
    params: z.object({
      requestId: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .openapi({
          param: {
            name: 'requestId',
            in: 'path',
            required: true,
            style: 'simple',
            explode: false,
            schema: { type: 'integer', format: 'int64' },
          },
        }),
    }),
    query: z.object({
      type: z
        .enum(['response', 'update'])
        .openapi({
          param: {
            name: 'type',
            in: 'query',
            required: true,
            style: 'form',
            explode: false,
            schema: { type: 'string', enum: ['response', 'update'] },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Returns status for account management request',
      content: {
        'application/json': {
          schema: z.xor([AmRequestStatusResponseSchema, StatusResponseSchema]),
        },
      },
    },
    400: {
      description: 'Returns error description representing bad request',
      content: { 'application/problem+json': { schema: ProblemDetailResponseSchema } },
    },
    401: {
      description: 'Returns error description representing access issue',
      content: { 'application/problem+json': { schema: ProblemDetailResponseSchema } },
    },
    403: {
      description: 'Returns error description representing access issue',
      content: { 'application/problem+json': { schema: ProblemDetailResponseSchema } },
    },
    415: {
      description: 'Unsupported Media Type',
      content: { '*/*': { schema: z.record(z.string(), z.object({})) } },
    },
    500: {
      description: 'Returns error description representing internal server error',
      content: { 'application/problem+json': { schema: ProblemDetailResponseSchema } },
    },
  },
  security: [{ oauth2Bearer: [] }],
})

