export const getGwApiV1RequestsRoute = createRoute({
  method: 'get',
  path: '/gw/api/v1/requests',
  tags: ['Account Management Utilities'],
  summary: "Get Requests' Details By Timeframe",
  description:
    "Fetch Requests' Details By Timeframe<br><br>**Scope**: `accounts.read`<br>**Security Policy**: `HTTPS`",
  operationId: 'listRequests',
  request: {
    query: z.object({
      requestDetails: z
        .preprocess(
          (val) => {
            if (typeof val !== 'string') return val
            const parts = val.split(',')
            if (parts.length % 2 !== 0) return val
            return Object.fromEntries(
              parts.flatMap((part, i) => (i % 2 === 0 ? [[part, parts[i + 1]]] : [])),
            )
          },
          z.object({
            startDate: z.iso.date(),
            endDate: z.iso.date(),
            offset: z
              .preprocess((val) => {
                if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
                  return val
                if (/^-?\d+$/.test(val)) return BigInt(val)
                const num = Number(val)
                return Number.isSafeInteger(num) ? BigInt(num) : val
              }, z.int64().min(0n))
              .exactOptional()
              .openapi({ type: 'integer', format: 'int64', minimum: 0 }),
            limit: z
              .preprocess((val) => {
                if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
                  return val
                if (/^-?\d+$/.test(val)) return BigInt(val)
                const num = Number(val)
                return Number.isSafeInteger(num) ? BigInt(num) : val
              }, z.int64().min(1n).max(1000n))
              .exactOptional()
              .openapi({ type: 'integer', format: 'int64', minimum: 1, maximum: 1000 }),
            status: z
              .enum(['N', 'O', 'P', 'C', 'A', 'E', 'F', 'I', 'J', 'L', 'M', 'R', 'W', 'Q'])
              .exactOptional(),
          }),
        )
        .openapi({
          param: {
            name: 'requestDetails',
            in: 'query',
            required: true,
            style: 'form',
            explode: false,
            schema: {
              required: ['endDate', 'startDate'],
              type: 'object',
              properties: {
                startDate: { type: 'string', format: 'date' },
                endDate: { type: 'string', format: 'date' },
                offset: { minimum: 0, type: 'integer', format: 'int64' },
                limit: { maximum: 1000, minimum: 1, type: 'integer', format: 'int64' },
                status: {
                  type: 'string',
                  enum: ['N', 'O', 'P', 'C', 'A', 'E', 'F', 'I', 'J', 'L', 'M', 'R', 'W', 'Q'],
                },
              },
            },
          },
          required: ['endDate', 'startDate'],
        }),
    }),
  },
  responses: {
    200: {
      description: "Fetch Requests' Details By Timeframe",
      content: { 'application/json': { schema: RequestDetailsResponseSchema } },
    },
    400: {
      description: 'Returns error description representing bad request',
      content: { 'application/problem+json': { schema: ProblemDetailResponseSchema } },
    },
    401: {
      description: 'Returns error description representing access issue',
      content: { 'application/problem+json': { schema: ProblemDetailResponseSchema } },
    },
    403: {
      description: 'Returns error description representing access issue',
      content: { 'application/problem+json': { schema: ProblemDetailResponseSchema } },
    },
    415: {
      description: 'Unsupported Media Type',
      content: { '*/*': { schema: z.record(z.string(), z.object({})) } },
    },
    500: {
      description: 'Returns error description representing internal server error',
      content: { 'application/problem+json': { schema: ProblemDetailResponseSchema } },
    },
  },
  security: [{ oauth2Bearer: [] }],
})

export const getGwApiV1RestrictionsAccountRoute = createRoute({
  method: 'get',
  path: '/gw/api/v1/restrictions/account',
  tags: ['PreTrade Compliance Restrictions'],
  summary: 'Get Restriction IDs For An Account',
  description:
    "Returns all restriction IDs for the given account. The account must be the caller's master account or a direct sub-account. Returns 403 for both unauthorized and non-existent accounts to prevent ID enumeration.<br><br>**Scope**: `restrictions.read`<br>**Security Policy**: `HTTPS`",
  operationId: 'getAccountRestrictions',
  request: {
    headers: z.object({
      Authorization: z
        .string()
        .openapi({
          param: {
            name: 'Authorization',
            in: 'header',
            description:
              'RS256-signed JWT (Bearer format), signed with your registered private key. Must contain an `accountId` claim identifying the master account. A missing or invalid token returns HTTP 401.',
            required: true,
            style: 'simple',
            explode: false,
            schema: {
              type: 'string',
              example: 'Bearer eyJ0eXAiOiJKV1QiLCJhbGciOiJSUzI1NiIsImtpZCI6ImNsaWVudC1r...',
            },
          },
          example: 'Bearer eyJ0eXAiOiJKV1QiLCJhbGciOiJSUzI1NiIsImtpZCI6ImNsaWVudC1r...',
        }),
    }),
    query: z.object({
      masterUserName: MasterUserNameParamsSchema,
      accountId: z
        .string()
        .max(64)
        .openapi({
          param: {
            name: 'accountId',
            in: 'query',
            description: 'Master or sub-account ID. Max 64 characters.',
            required: true,
            style: 'form',
            explode: false,
            schema: { maxLength: 64, type: 'string', example: 'U1000000' },
          },
          example: 'U1000000',
        }),
      isEmpTrack: IsEmpTrackParamsSchema,
    }),
  },
  responses: {
    200: {
      description: 'Restriction IDs for the account.',
      content: {
        'application/json': {
          schema: AccountRestrictionsResponseSchema,
          examples: {
            withRestrictions: {
              summary: 'Account with restrictions',
              value: { status: 'ok', accountId: 'U1000000', restrictionIds: [1001, 1002, 1003] },
            },
            noRestrictions: {
              summary: 'Account with no restrictions',
              value: { status: 'ok', accountId: 'U1000000', restrictionIds: [] },
            },
          },
        },
      },
    },
    400: BadRequestResponse,
    401: UnauthorizedResponse,
    403: ForbiddenResponse,
    500: InternalErrorResponse,
  },
  security: [{ oauth2Bearer: [] }],
})

