export const getGwApiV1RestrictionsRestrictionRoute = createRoute({
  method: 'get',
  path: '/gw/api/v1/restrictions/restriction',
  tags: ['PreTrade Compliance Restrictions'],
  summary: 'Get Restriction Details',
  description:
    'Returns full details of a restriction including rules. The restriction must be owned by the caller. Returns 403 for both unauthorized and non-existent restrictions to prevent ID enumeration.<br><br>**Scope**: `restrictions.read`<br>**Security Policy**: `HTTPS`',
  operationId: 'getRestrictionDetails',
  request: {
    headers: z.object({
      Authorization: z
        .string()
        .openapi({
          param: {
            name: 'Authorization',
            in: 'header',
            description:
              'RS256-signed JWT (Bearer format), signed with your registered private key. Must contain an `accountId` claim identifying the master account. A missing or invalid token returns HTTP 401.',
            required: true,
            style: 'simple',
            explode: false,
            schema: {
              type: 'string',
              example: 'Bearer eyJ0eXAiOiJKV1QiLCJhbGciOiJSUzI1NiIsImtpZCI6ImNsaWVudC1r...',
            },
          },
          example: 'Bearer eyJ0eXAiOiJKV1QiLCJhbGciOiJSUzI1NiIsImtpZCI6ImNsaWVudC1r...',
        }),
    }),
    query: z.object({
      masterUserName: MasterUserNameParamsSchema,
      restrictionId: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64().min(1n))
        .openapi({
          param: {
            name: 'restrictionId',
            in: 'query',
            description: 'Positive integer. Decimals and non-numeric values return 400.',
            required: true,
            style: 'form',
            explode: false,
            schema: { minimum: 1, type: 'integer', format: 'int64', example: 1001 },
          },
          example: 1001,
        }),
      isEmpTrack: IsEmpTrackParamsSchema,
    }),
  },
  responses: {
    200: {
      description: 'Full restriction details.',
      content: {
        'application/json': {
          schema: RestrictionDetailsResponseSchema,
          examples: {
            withRule: {
              summary: 'Restriction with one rule',
              value: {
                restrictionId: 1001,
                name: 'My Restriction',
                description: null,
                message: null,
                applicationType: 'Restrict',
                usageType: 'Trading',
                allowOnly: null,
                matchAll: null,
                isWhiteList: 'F',
                rules: [
                  {
                    ruleId: 5001,
                    type: 'RESTRICTALLORDERS',
                    validityType: 'GTC',
                    params: [{ orderside: 'ALL' }],
                  },
                ],
                status: 'ok',
              },
            },
            withTradeMonitoring: {
              summary: 'Restriction with trade-monitoring',
              value: {
                restrictionId: 1002,
                name: 'My TM Restriction',
                description: null,
                message: null,
                applicationType: 'Restrict',
                usageType: 'Monitor',
                allowOnly: null,
                matchAll: null,
                isWhiteList: 'F',
                rules: [],
                tmFrequency: 'Daily',
                tmFirstDate: 1700000000000,
                status: 'ok',
              },
            },
          },
        },
      },
    },
    400: BadRequestResponse,
    401: UnauthorizedResponse,
    403: ForbiddenResponse,
    500: InternalErrorResponse,
  },
  security: [{ oauth2Bearer: [] }],
})

export const getGwApiV1RestrictionsRestrictionScopeRoute = createRoute({
  method: 'get',
  path: '/gw/api/v1/restrictions/restriction-scope',
  tags: ['PreTrade Compliance Restrictions'],
  summary: 'Get Restriction Scope',
  description:
    "Returns a restriction's scope (`Active For Family`, `Active Except`, `Active For Some`, or `Inactive`) and the account IDs relevant to that scope. `accountIds` is omitted for `Active For Family` and `Inactive` (implicit: all/no accounts). For `Active For Some`, `accountIds` is capped at a configurable limit (default 10000) with a `truncated` flag indicating whether more accounts exist beyond the cap. For `Active Except`, `accountIds` (the excluded accounts) is always returned in full, uncapped. The restriction must be owned by the caller's master account. Employee-track (`isEmpTrack=T`) callers are not supported.<br><br>**Scope**: `restrictions.read`<br>**Security Policy**: `HTTPS`",
  operationId: 'getRestrictionScope',
  request: {
    headers: z.object({
      Authorization: z
        .string()
        .openapi({
          param: {
            name: 'Authorization',
            in: 'header',
            description:
              'RS256-signed JWT (Bearer format), signed with your registered private key. Must contain an `accountId` claim identifying the master account. A missing or invalid token returns HTTP 401.',
            required: true,
            style: 'simple',
            explode: false,
            schema: {
              type: 'string',
              example: 'Bearer eyJ0eXAiOiJKV1QiLCJhbGciOiJSUzI1NiIsImtpZCI6ImNsaWVudC1r...',
            },
          },
          example: 'Bearer eyJ0eXAiOiJKV1QiLCJhbGciOiJSUzI1NiIsImtpZCI6ImNsaWVudC1r...',
        }),
    }),
    query: z.object({
      masterUserName: MasterUserNameParamsSchema,
      restrictionId: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64().min(1n))
        .openapi({
          param: {
            name: 'restrictionId',
            in: 'query',
            description: 'Positive integer. Decimals and non-numeric values return 400.',
            required: true,
            style: 'form',
            explode: false,
            schema: { minimum: 1, type: 'integer', format: 'int64', example: 1001 },
          },
          example: 1001,
        }),
      isEmpTrack: IsEmpTrackParamsSchema,
    }),
  },
  responses: {
    200: {
      description: 'Restriction scope and relevant account IDs.',
      content: {
        'application/json': {
          schema: RestrictionScopeResponseSchema,
          examples: {
            family: {
              summary: 'Active for family',
              value: { status: 'ok', restrictionId: 1001, scope: 'Active For Family' },
            },
            except: {
              summary: 'Active except',
              value: {
                status: 'ok',
                restrictionId: 1002,
                scope: 'Active Except',
                accountIds: ['U1000001'],
              },
            },
            some: {
              summary: 'Active for some',
              value: {
                status: 'ok',
                restrictionId: 1003,
                scope: 'Active For Some',
                accountIds: ['U1000000', 'U1000002'],
                truncated: false,
              },
            },
            inactive: {
              summary: 'Inactive',
              value: { status: 'ok', restrictionId: 1004, scope: 'Inactive' },
            },
          },
        },
      },
    },
    400: BadRequestResponse,
    401: UnauthorizedResponse,
    403: ForbiddenResponse,
    500: InternalErrorResponse,
  },
  security: [{ oauth2Bearer: [] }],
})

