export const getV1ApiFyiUnreadnumberRoute = createRoute({
  method: 'get',
  path: '/v1/api/fyi/unreadnumber',
  tags: ['Trading FYIs and Notifications'],
  summary: 'Get Number Of Unread Notifications',
  description: 'Returns the total number of unread notifications',
  operationId: 'getUnreadFyis',
  responses: {
    200: {
      description: 'Indicates data is being returned successfully.',
      content: {
        'application/json': {
          schema: z
            .object({
              BN: z
                .preprocess(
                  (val) =>
                    typeof val === 'number' && Number.isSafeInteger(val)
                      ? BigInt(val)
                      : typeof val === 'string' && /^-?\d+$/.test(val)
                        ? BigInt(val)
                        : val,
                  z.int64(),
                )
                .exactOptional()
                .openapi({
                  type: 'integer',
                  format: 'int64',
                  description: 'Returns the number of unread notifications.',
                }),
            })
            .openapi({ required: [] }),
          examples: { unreadnumber: { value: { BN: 4 } } },
        },
      },
    },
    401: UnauthorizedResponse,
    423: {
      description:
        'Return if called too frequently. Should not be called more than 1 time in 5 minutes',
      content: {
        'application/json': {
          schema: z.object({ status: z.string().exactOptional() }).openapi({ required: [] }),
        },
      },
    },
    500: InternalServerErrorResponse,
    503: ServiceUnavailableResponse,
  },
  security: [{ ssoBearer: [] }],
})

export const getV1ApiIserverAccountAlertAlertIdRoute = createRoute({
  method: 'get',
  path: '/v1/api/iserver/account/alert/{alertId}',
  tags: ['Trading Alerts'],
  summary: 'Details Of A Specific Alert',
  description: 'Request details of a specific alert by providing the assigned alertId Id.',
  operationId: 'getAlertDetails',
  request: {
    params: z.object({
      alertId: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .openapi({
          param: {
            name: 'alertId',
            in: 'path',
            required: true,
            style: 'simple',
            explode: false,
            schema: {
              type: 'integer',
              description: 'alert identifier, internally referenced as order id',
              format: 'int64',
            },
          },
          description: 'alert identifier, internally referenced as order id',
        }),
    }),
    query: z.object({
      type: z
        .literal('Q')
        .openapi({
          param: {
            name: 'type',
            in: 'query',
            required: true,
            style: 'form',
            explode: false,
            schema: { type: 'string', description: 'queryType', enum: ['Q'] },
          },
          description: 'queryType',
        }),
    }),
  },
  responses: {
    200: {
      description: 'An object containing all unique details of the specified alert.',
      content: {
        'application/json': {
          schema: AlertDetailsSchema,
          examples: {
            'found-alert': {
              value: {
                account: 'U1234567',
                order_id: 833967258,
                alert_name: 'IBM',
                tif: 'GTC',
                expire_time: null,
                alert_active: 1,
                alert_repeatable: 0,
                alert_email: 'john.smith@example.com',
                alert_send_message: 1,
                alert_message: 'alert message',
                alert_show_popup: 1,
                alert_play_audio: null,
                order_status: 'Submitted',
                alert_triggered: false,
                fg_color: '#FFFFFF',
                bg_color: '#0000CC',
                order_not_editable: false,
                itws_orders_only: 0,
                alert_mta_currency: null,
                alert_mta_defaults: null,
                tool_id: null,
                time_zone: null,
                alert_default_type: null,
                condition_size: 1,
                condition_outside_rth: 1,
                conditions: [
                  {
                    condition_type: 1,
                    conidex: '8314@NYSE',
                    contract_description_1: 'IBM',
                    condition_operator: '>=',
                    condition_trigger_method: '0',
                    condition_value: '500.00',
                    condition_logic_bind: 'n',
                    condition_time_zone: null,
                  },
                ],
              },
            },
          },
        },
      },
    },
    400: {
      description: 'bad request if orderId is empty or type is invalid',
      content: {
        'application/json; charset=utf-8': {
          schema: ErrorResponse2Schema,
          examples: {
            'bad-request': {
              value: { error: 'Bad Request: orderId and type are required', statusCode: 400 },
            },
          },
        },
      },
    },
    401: UnauthorizedResponse,
    500: {
      description: 'orderId is not parsable; unable to process request',
      content: { 'application/json; charset=utf-8': { schema: ErrorResponse2Schema } },
    },
    503: ServiceUnavailableResponse,
  },
  security: [{ ssoBearer: [] }],
})

