                  size: 5,
                  price: '192.26',
                  order_ref: 'Order123',
                  submitter: 'user1234',
                  exchange: 'ISLAND',
                  commission: '1.01',
                  net_amount: 961.3,
                  account: 'U1234567',
                  accountCode: 'U1234567',
                  account_allocation_name: 'U1234567',
                  company_name: 'APPLE INC',
                  contract_description_1: 'AAPL',
                  sec_type: 'STK',
                  listing_exchange: 'NASDAQ.NMS',
                  conid: 265598,
                  conidEx: '265598',
                  clearing_id: 'IB',
                  clearing_name: 'IB',
                  liquidation_trade: '0',
                  is_event_trading: '0',
