export const getV1ApiTrsrvAllConidsRoute = createRoute({
  method: 'get',
  path: '/v1/api/trsrv/all-conids',
  tags: ['Trading Contracts'],
  summary: 'List All Stock Conids By Exchange',
  description:
    'Send out a request to retrieve all contracts made available on a requested exchange. This returns all contracts that are tradable on the exchange, even those that are not using the exchange as their primary listing.',
  operationId: 'getConidsByExchange',
  request: {
    query: z.object({
      exchange: z
        .string()
        .openapi({
          param: {
            name: 'exchange',
            in: 'query',
            required: true,
            style: 'form',
            explode: false,
            schema: {
              type: 'string',
              description: 'Exchange from which derivatives should be retrieved from.',
              example: 'AMEX',
            },
          },
          description: 'Exchange from which derivatives should be retrieved from.',
          example: 'AMEX',
        }),
      assetClass: z
        .any()
        .default('STK')
        .exactOptional()
        .openapi({
          param: {
            name: 'assetClass',
            in: 'query',
            required: false,
            style: 'form',
            explode: false,
            schema: { description: 'asset class', default: 'STK' },
          },
          description: 'asset class',
        }),
    }),
  },
  responses: {
    200: {
      description: "Successful response containing a contract's security definition.",
      content: {
        'application/json': {
          schema: z.array(
            z
              .object({
                ticker: z
                  .string()
                  .exactOptional()
                  .openapi({ description: 'The ticker symbol of the contract.' }),
                conid: z
                  .preprocess(
                    (val) =>
                      typeof val === 'number' && Number.isSafeInteger(val)
                        ? BigInt(val)
                        : typeof val === 'string' && /^-?\d+$/.test(val)
                          ? BigInt(val)
                          : val,
                    z.int64(),
                  )
                  .exactOptional()
                  .openapi({
                    type: 'integer',
                    format: 'int64',
                    description: 'The contract identifier of the returned contract.',
                  }),
                exchange: z
                  .string()
                  .exactOptional()
                  .openapi({ description: 'The primary exchange of the returned contract.' }),
              })
              .openapi({ required: [] }),
          ),
          examples: {
            response: {
              value: [
                { ticker: 'BMO', conid: 5094, exchange: 'NYSE' },
                { ticker: 'BNS', conid: 15156975, exchange: 'NYSE' },
              ],
            },
          },
        },
      },
    },
    401: UnauthorizedResponse,
    500: InternalServerErrorResponse,
    503: ServiceUnavailableResponse,
  },
  security: [{ ssoBearer: [] }],
})

